import hashlib
import hmac
import os
import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key-change-in-prod')
SESSION_DURATION = 3600

# Custom base32 alphabet for URL-safe tokens
ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
DECODE_MAP = {c: i for i, c in enumerate(ALPHABET)}

def encode_token_bytes(data: bytes) -> str:
    """Encode bytes to base32 string."""
    result = []
    buffer = 0
    bits_left = 0
    for byte in data:
        buffer = (buffer << 8) | byte
        bits_left += 8
        while bits_left >= 5:
            bits_left -= 5
            result.append(ALPHABET[(buffer >> bits_left) & 0x1F])
    if bits_left > 0:
        result.append(ALPHABET[(buffer << (5 - bits_left)) & 0x1F])
    return ''.join(result)

def decode_token_bytes(token: str) -> bytes:
    """Decode base32 string back to bytes."""
    result = []
    buffer = 0
    bits_left = 0
    for char in token:
        if char not in DECODE_MAP:
            raise ValueError(f"Invalid character in token: {char}")
        buffer = (buffer << 5) | DECODE_MAP[char]
        bits_left += 5
        while bits_left >= 8:
            bits_left -= 8
            # Extract byte from buffer
            byte_val = (buffer >> bits_left)
            result.append(byte_val)
            buffer = buffer & ((1 << bits_left) - 1)
    return bytes(result)

def create_signed_token(user_id: str, role: str, issued_at: int) -> str:
    """Create HMAC-signed token with user claims."""
    payload = json.dumps({
        'sub': user_id,
        'role': role,
        'iat': issued_at,
        'exp': issued_at + SESSION_DURATION
    }, separators=(',', ':')).encode('utf-8')

    # Compute HMAC-SHA256
    mac = hmac.new(SECRET_KEY.encode('utf-8'), payload, hashlib.sha256).digest()

    # Token format: payload_length(2 bytes) + payload + hmac(32 bytes)
    token_bytes = len(payload).to_bytes(2, 'big') + payload + mac
    return encode_token_bytes(token_bytes)

def verify_signed_token(token_str: str) -> dict:
    """Verify and decode a signed token. Returns claims or None."""
    try:
        token_bytes = decode_token_bytes(token_str)
    except (ValueError, Exception):
        return None

    if len(token_bytes) < 34:  # 2 + min 0 payload + 32 hmac
        return None

    payload_len = (token_bytes[0] << 8) | token_bytes[1]

    if payload_len < 0 or payload_len > len(token_bytes) - 34:
        return None

    payload = token_bytes[2:2 + payload_len]
    provided_mac = token_bytes[2 + payload_len:2 + payload_len + 32]

    if len(provided_mac) != 32:
        return None

    # Verify HMAC
    expected_mac = hmac.new(
        SECRET_KEY.encode('utf-8'), bytes(payload), hashlib.sha256
    ).digest()

    if not hmac.compare_digest(bytes(provided_mac), expected_mac):
        return None

    try:
        claims = json.loads(bytes(payload).decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None

    # Check expiration
    if claims.get('exp', 0) < time.time():
        return None

    return claims

class TokenNonce:
    """Nonce generator for replay protection."""
    def __init__(self):
        self._counter = int.from_bytes(os.urandom(8), 'big')
        self._used = set()

    def generate(self) -> int:
        self._counter = (self._counter + 1) & 0xFFFFFFFFFFFFFFFF
        return self._counter

    def mark_used(self, nonce: int) -> bool:
        if nonce in self._used:
            return False
        self._used.add(nonce)
        # Prune old nonces periodically
        if len(self._used) > 10000:
            self._used = set(list(self._used)[-5000:])
        return True

nonce_gen = TokenNonce()

class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/login':
            self._handle_login()
        elif self.path == '/verify':
            self._handle_verify()
        else:
            self.send_error(404)

    def _handle_login(self):
        content_len = int(self.headers.get('Content-Length', 0))
        if content_len > 2048:
            self.send_error(413)
            return
        body = self.rfile.read(content_len)
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self.send_error(400)
            return

        username = data.get('username', '')
        password = data.get('password', '')

        if not isinstance(username, str) or not isinstance(password, str):
            self.send_error(400)
            return

        # Simplified auth check
        if not self._authenticate(username, password):
            self.send_error(401)
            return

        role = 'admin' if username == 'admin' else 'user'
        token = create_signed_token(username, role, int(time.time()))
        nonce = nonce_gen.generate()

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({
            'token': token,
            'nonce': nonce
        }).encode())

    def _handle_verify(self):
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            self.send_error(401)
            return

        token_str = auth[7:]
        # Validate token characters
        if not all(c in ALPHABET for c in token_str):
            self.send_error(401)
            return
        if len(token_str) > 1024:
            self.send_error(401)
            return

        claims = verify_signed_token(token_str)
        if claims is None:
            self.send_error(401)
            return

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({
            'user': claims.get('sub'),
            'role': claims.get('role'),
            'valid': True
        }).encode())

    def _authenticate(self, username: str, password: str) -> bool:
        # In production, check against secure credential store
        users = {'admin': 'admin_pass_123', 'user1': 'user_pass_456'}
        expected = users.get(username)
        if expected is None:
            # Constant-time comparison against dummy to prevent timing
            hmac.compare_digest(password, 'dummy_constant_value')
            return False
        return hmac.compare_digest(password, expected)

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    server.serve_forever()
